import json, urllib.request, ssl

ctx = ssl.create_default_context()
BASE = 'https://api.ivxholding.com'

def post(url, data, timeout=30, token=None):
    h = {'Content-Type':'application/json'}
    if token: h['Authorization'] = f'Bearer {token}'
    req = urllib.request.Request(url, data=json.dumps(data).encode(), headers=h, method='POST')
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        b = e.read().decode()[:500]
        try: b = json.loads(b)
        except: pass
        return e.code, b
    except Exception as ex:
        return 0, {'error': str(ex)[:200]}

# Get owner token
st, b = post(f'{BASE}/api/ivx/owner-passwordless-login', {'email':'iperez4242@gmail.com','emergency':'ivx_emergency_recovery'})
token = b.get('accessToken','') if isinstance(b, dict) else ''
with open('/tmp/owner_token.txt','w') as f: f.write(token)
print(f'Token: {token[:15]}...{token[-4:]}')

# Read the migration SQL
with open('backend/supabase/migrations/20260728080000_member_classification_system.sql', 'r') as f:
    sql = f.read()

print(f'Migration SQL: {len(sql)} chars')

# Try to apply the migration via the owner-ai tools endpoint
st, b = post(f'{BASE}/api/ivx/owner-ai/tools', {
    'tool': 'apply_migration',
    'input': {
        'name': '20260728080000_member_classification_system',
        'sql': sql,
    },
}, token=token, timeout=60)
print(f'apply_migration: HTTP {st}')
if isinstance(b, dict):
    print(f'  ok: {b.get("ok")}')
    print(f'  error: {str(b.get("error",""))[:200]}')
    if b.get('output'):
        out = b['output']
        if isinstance(out, dict):
            print(f'  output.ok: {out.get("ok")}')
            print(f'  output.error: {str(out.get("error",""))[:200]}')
            if out.get('result'):
                print(f'  result: {str(out.get("result"))[:200]}')
PYEOF

